package com.poi.investment.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long minutes; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-minutes}") long minutes){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must be at least 32 bytes");this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String issue(AppUserPrincipal user){Instant now=Instant.now();return Jwts.builder().subject(user.username()).claim("role",user.role()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(Duration.ofMinutes(minutes)))).signWith(key).compact();} public AppUserPrincipal identity(String token){var claims=Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();return new AppUserPrincipal(claims.getSubject(),claims.get("role",String.class));} public String subject(String token){return identity(token).username();} public record AppUserPrincipal(String username,String role){} }
